draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(W, H);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(W, 0);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 20 * Math.cos(t), 0);
  ctx.lineTo(W / 2 - 20 * Math.cos(t), H);
  ctx.stroke();
  ctx.restore();
}
